css:
body :where([data-bz-node="im"]) .bz-block{padding:0}
body :where([data-bz-node="im"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="im"]>.bz-container{padding-inline:0}

body [data-bz-node="im"]{background:#fff;padding:96px 0 90px}
body [data-bz-node="im"]>.bz-container{max-width:var(--container)}
body [data-bz-node="im-row"]{display:grid;grid-template-columns:1fr 1fr;gap:0 64px;align-items:center}
body [data-bz-node="im-row"]>.bz-col{grid-column:auto}
body [data-bz-node="im-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px}
body [data-bz-node="im-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;max-width:520px}
body [data-bz-node="im-text"] .bz-text{max-width:520px;margin-top:24px}
body [data-bz-node="im-text"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="im-text"] p:last-child{margin:0}
body [data-bz-node="im-cta"]{margin-top:28px}
body [data-bz-node="im-cta"] .bz-btns{margin:0}
body [data-bz-node="im-cta"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:50px;padding:0 28px;border:0;border-radius:2px;background:var(--accent);color:#fff;font:700 11px/1 var(--font-body);letter-spacing:.18em;text-transform:uppercase;text-decoration:none}
body [data-bz-node="im-cta"] .bz-btn:hover{background:var(--accent-dark)}
body [data-bz-node="im-media"] figure{margin:0}
body [data-bz-node="im-media"] img{width:100%;height:auto;border-radius:0}
body [data-bz-node="im-badge"]{display:flex;justify-content:center;margin-top:56px}
body [data-bz-node="im-badge-col"]{display:flex;align-items:center;justify-content:center;gap:22px}
body [data-bz-node="im-badge-col"] .bz-block{width:auto}
body [data-bz-node="im-logo"] img{width:160px;height:auto}
body [data-bz-node="im-logo"] figure{margin:0}
body [data-bz-node="im-badge-text"]{border-left:1px solid #cfcfcd;padding-left:22px}
body [data-bz-node="im-badge-text"] p{font:400 14px/1.7 var(--font-body);color:#555;margin:0}
@media (max-width:1100px){body [data-bz-node="im"]{padding:64px 24px}body [data-bz-node="im-row"]{grid-template-columns:1fr;gap:32px}body [data-bz-node="im-h"] h2{font-size:30px}body [data-bz-node="im-badge"]{margin-top:40px}}
@media (max-width:640px){body [data-bz-node="im"]{padding:48px 20px}body [data-bz-node="im-h"] h2{font-size:26px}body [data-bz-node="im-cta"] .bz-btn{width:100%}body [data-bz-node="im-logo"] img{width:120px}}
